      "position": "PARTIAL",
      "evidence": "Separate, higher or uncapped protection for title, capacity, tax, IP, fraud and specific indemnities."
    },
    {
      "issue_id": "SPA-N-002",
      "position": "PARTIAL",
      "evidence": "The basket should not apply to fundamental matters, tax, fraud or specific indemnities."
    },
    {
      "issue_id": "SPA-N-003",
      "position": "PARTIAL",
      "evidence": "Exclude tax and IP claims from the general cap and short limitation period, or apply tailored caps and periods."
    },
    {
      "issue_id": "SPA-N-004",
      "position": "PUSHBACK",
      "evidence": "Fundamental/title/capacity warranties should be uncapped or subject to a substantially higher cap, with a longer survival period."
    },
    {
      "issue_id": "SPA-N-005",
      "position": "PUSHBACK",
      "evidence": "Separate, higher or uncapped protection for title, capacity, tax, IP, fraud and specific indemnities."
    },
    {
      "issue_id": "SPA-N-006",
      "position": "PUSHBACK",
      "evidence": "Exclude generic data-room and public-register disclosure from qualifying warranties."
    },
    {
      "issue_id": "SPA-N-007",
      "position": "PUSHBACK",
      "evidence": "Limit the exclusion to the actual knowledge of specifically named Buyer representatives."
    },
    {
      "issue_id": "SPA-N-008",
      "position": "PUSHBACK",
      "evidence": "Make delivery of an unconditional written Bluefen consent, and satisfaction of all related conditions, a condition precedent to Completion."
    },
    {
      "issue_id": "SPA-N-009",
      "position": "PUSHBACK",
      "evidence": "Do not accept a post-Completion release as sufficient protection."
    },
    {
      "issue_id": "SPA-N-010",
      "position": "PUSHBACK",
      "evidence": "Include the gross amount in the Completion funds flow or deduct it from the purchase price."
    },
    {
      "issue_id": "SPA-N-011",
      "position": "PUSHBACK",
      "evidence": "Expand the indemnity to cover all losses arising from failure to obtain the materials, third-party claims, replacement development and infringement/non-use risk."
    },
    {
      "issue_id": "SPA-N-012",
      "position": "PUSHBACK",
      "evidence": "This should not be left under the general warranty regime."
    },
    {
      "issue_id": "SPA-N-013",
      "position": "PUSHBACK",
      "evidence": "Treat unavoidable post-Completion commitments as a price adjustment or require Seller reimbursement."
    },
    {
      "issue_id": "SPA-N-014",
      "position": "PUSHBACK",
      "evidence": "Separate, higher or uncapped protection for title, capacity, tax, IP, fraud and specific indemnities."
    },
    {
      "issue_id": "SPA-N-015",
      "position": "PUSHBACK",
      "evidence": "A share register is evidence, but it is not a complete title package."
    },
    {
      "issue_id": "SPA-N-016",
      "position": "PUSHBACK",
      "evidence": "Include a standalone tax indemnity for all pre-Completion tax liabilities"
    }
  ],
